class App:
    def __init__(self):
        self.routes = {}
    def get(self, path):
        def decorator(func):
            self.routes[path] = func
            return func
        return decorator

APP_VERSION = "1.2.0"
app = App()

@app.get("/health")
def health():
    return {"ok": True, "version": APP_VERSION}

result = app.routes["/health"]()

